import{_ as s,o as t,c as a,a2 as e}from"./chunks/framework.BU4O3IzQ.js";const o=JSON.parse('{"title":"GitHub加速下载项目的方法","description":"","frontmatter":{"title":"GitHub加速下载项目的方法","date":"2020-03-09T00:00:00.000Z","tags":["GitHub"],"section":"tech"},"headers":[],"relativePath":"tech/github/GitHub加速下载项目的方法.md","filePath":"tech/github/GitHub加速下载项目的方法.md","lastUpdated":1786092171000}'),h={name:"tech/github/GitHub加速下载项目的方法.md"};function l(p,i,n,k,r,g){return t(),a("div",null,[...i[0]||(i[0]=[e(`<h1 id="github加速下载项目的方法" tabindex="-1">GitHub加速下载项目的方法 <a class="header-anchor" href="#github加速下载项目的方法" aria-label="Permalink to &quot;GitHub加速下载项目的方法&quot;">​</a></h1><p class="article-meta"><time datetime="2020-03-09">2020-03-09</time><span class="article-tag">GitHub</span></p><p>国内在github上克隆项目总是异常的慢，据我多次克隆观察，下载速度最快就20k/s左右，特别是在克隆比较大的项目时简直慢得无法忍受！下面介绍一种加载克隆项目的方法。</p><p><img src="https://cdn.jsdelivr.net/gh/xugaoyi/image_store/blog/20200309112604.png" alt=""></p><h2 id="利用码云来转接做下载加速" tabindex="-1">利用码云来转接做下载加速 <a class="header-anchor" href="#利用码云来转接做下载加速" aria-label="Permalink to &quot;利用码云来转接做下载加速&quot;">​</a></h2><ol><li><p>首先你得有一个 <a href="https://gitee.com/" target="_blank" rel="noreferrer">码云</a> 的账号</p></li><li><p>登录码云之后在页面右上角的加号选择<code>从GitHub/GitLab导入项目</code></p><p><img src="https://cdn.jsdelivr.net/gh/xugaoyi/image_store/blog/20200309112711.jpg" alt=""></p></li><li><p>选择<code>从URL导入</code>，粘贴从GitHub复制来的仓库地址，然后导入，这个导入过程一般是很快的。</p><p><img src="https://cdn.jsdelivr.net/gh/xugaoyi/image_store/blog/20200309112710.jpg" alt=""></p></li><li><p>从码云克隆刚导入的这个项目，克隆速度会快很多，网速好的能达到几兆每秒（具体速度就看你的网速了，吐槽一下我家网速，总在关键时刻显示&quot;视频加载中&quot;....）</p><p><img src="https://cdn.jsdelivr.net/gh/xugaoyi/image_store/blog/20200309112712.jpg" alt=""></p></li><li><p>另外要注意的一点，克隆下来的项目关联的是码云的仓库，如果你需要关联github仓库需要更改远程仓库。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 查看关联的远程仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">仓库</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 删除远程仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">仓库</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">远程仓库地</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">址</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 关联远程仓库，仓库名一般使用origin</span></span></code></pre></div></li></ol><p>这个方法适合用于克隆比较大的项目，如果克隆小项目，20k/s的速度好像还能将就~~</p>`,7)])])}const c=s(h,[["render",l]]);export{o as __pageData,c as default};
